from functools import lru_cache
class Solution:
    def maximumANDSum(self, nums, numSlots):
        @lru_cache(None)
        def dp(i, mask):
            if i == len(nums):
                return 0
            best = 0
            for s in range(numSlots):
                for t in range(2):
                    b = 1 << (2 * s + t)
                    if not mask & b:
                        best = max(best, (nums[i] & (s + 1)) + dp(i + 1, mask | b))
            return best
        return dp(0, 0)

