        long long key = (long long)i << 20 | mask;
        auto it = memo.find(key);
        if (it != memo.end()) return it->second;
        int best = 0;
        for (int s = 0; s < ns_; s++)
            for (int t = 0; t < 2; t++) {
                int b = 1 << (2 * s + t);
                if (!(mask & b))
                    best = max(best, (nums_[i] & (s + 1)) + dp(i + 1, mask | b));
            }
        memo[key] = best;
        return best;
    }
public:
