class Solution {
    private int[] nums;
    private int ns;
    private Map<Long, Integer> memo = new HashMap<>();
    private int dp(int i, int mask) {
        if (i == nums.length) return 0;
        long key = (long) i << 20 | mask;
        Integer hit = memo.get(key);
        if (hit != null) return hit;
        int best = 0;
        for (int s = 0; s < ns; s++)
            for (int t = 0; t < 2; t++) {
                int b = 1 << (2 * s + t);
                if ((mask & b) == 0)
                    best = Math.max(best, (nums[i] & (s + 1)) + dp(i + 1, mask | b));
            }
        memo.put(key, best);
        return best;
    }
    public int maximumANDSum(int[] nums, int numSlots) {
        this.nums = nums; this.ns = numSlots;
        return dp(0, 0);
    }
}

