public:
    int maximumANDSum(vector<int>& nums, int numSlots) {
        int N = 2 * numSlots;
        vector<int> dp(1 << N, 0);
        int best = 0;
        for (int mask = 0; mask < (1 << N); mask++) {
            int i = __builtin_popcount(mask);
            if (i >= (int)nums.size()) continue;
            for (int s = 0; s < numSlots; s++)
                for (int t = 0; t < 2; t++) {
                    int b = 1 << (2 * s + t);
                    if (!(mask & b)) {
                        int nm = mask | b;
                        dp[nm] = max(dp[nm], dp[mask] + (nums[i] & (s + 1)));
                        if (i + 1 == (int)nums.size()) best = max(best, dp[nm]);
                    }
                }
        }
        return best;
    }
};

