class Solution {
    public int maximumANDSum(int[] nums, int numSlots) {
        int N = 2 * numSlots;
        int[] dp = new int[1 << N];
        int best = 0;
        for (int mask = 0; mask < (1 << N); mask++) {
            int i = Integer.bitCount(mask);
            if (i >= nums.length) continue;
            for (int s = 0; s < numSlots; s++)
                for (int t = 0; t < 2; t++) {
                    int b = 1 << (2 * s + t);
                    if ((mask & b) == 0) {
                        int nm = mask | b;
                        dp[nm] = Math.max(dp[nm], dp[mask] + (nums[i] & (s + 1)));
                        if (i + 1 == nums.length) best = Math.max(best, dp[nm]);
                    }
                }
        }
        return best;
    }
}

