        let i = 0, m = mask;
        while (m) { m &= m - 1; i++; }
        if (i >= nums.length) continue;
        for (let s = 0; s < numSlots; s++)
            for (let t = 0; t < 2; t++) {
                const b = 1 << (2 * s + t);
                if (!(mask & b)) {
                    const nm = mask | b;
                    dp[nm] = Math.max(dp[nm], dp[mask] + (nums[i] & (s + 1)));
                    if (i + 1 === nums.length) best = Math.max(best, dp[nm]);
                }
            }
    }
    return best;
};
